/*
 * prog52_bfs_grid.c
 *
 * Re‑implementation of the original obfuscated program.
 * It reads four integer arguments (start row, start col,
 * target row, target col) and runs a BFS on a fixed 5×5 grid.
 *
 * Output:
 *   INVALID_CELL   – if any coordinate is out of range or on a wall '#'
 *   UNREACHABLE    – if the target cannot be reached
 *   dist=%d        – distance (number of steps) from start to target
 *
 * The grid is stored with a stride of six, exactly as the original binary
 * expects.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

#define N 5               /* logical size of the grid (rows and columns) */
#define STRIDE 6          /* physical row length used by the original code */
#define MAX_Q (N * N)     /* maximum number of cells in the queue */

/* ----------------------------------------------------------------------
 * Fixed map – the same data that the original binary contains.
 * The layout matches the original indexing: index = row*STRIDE + col.
 *
 * The map is taken from the original binary (prog52_bfs_grid).  It is a
 * 5×5 maze; the extra column (index 5) is never accessed.
 * ---------------------------------------------------------------------- */
static const char grid[STRIDE * N] = {
    /* row 0 */ '.', '.', '.', '.', '.', 0,
    /* row 1 */ '.', '#', '#', '.', '.', 0,
    /* row 2 */ '.', '.', '#', '.', '.', 0,
    /* row 3 */ '.', '#', '.', '.', '.', 0,
    /* row 4 */ '.', '.', '.', '#', '.', 0
};

/* ----------------------------------------------------------------------
 * Helper: test whether a cell is inside the logical board and not a wall.
 * ---------------------------------------------------------------------- */
static bool valid_cell(int r, int c)
{
    if (r < 0 || r >= N || c < 0 || c >= N)
        return false;
    return grid[r * STRIDE + c] != '#';
}

/* ----------------------------------------------------------------------
 * Breadth‑first search.
 * Returns:
 *   -1  : unreachable
 *   >=0 : distance from start to target
 * ---------------------------------------------------------------------- */
static int bfs(int sr, int sc, int tr, int tc)
{
    int visited[N][N] = {0};
    int dist   [N][N] = {0};
    int q_row[MAX_Q];
    int q_col[MAX_Q];
    int head = 0, tail = 0;

    /* enqueue start */
    q_row[tail] = sr;
    q_col[tail] = sc;
    ++tail;
    visited[sr][sc] = 1;
    dist   [sr][sc] = 0;

    /* direction vectors: up, down, left, right */
    const int dr[4] = {-1, 1, 0, 0};
    const int dc[4] = { 0, 0,-1, 1};

    while (head < tail) {
        int r = q_row[head];
        int c = q_col[head];
        ++head;

        if (r == tr && c == tc)
            return dist[r][c];               /* target reached */

        for (int d = 0; d < 4; ++d) {
            int nr = r + dr[d];
            int nc = c + dc[d];

            if (valid_cell(nr, nc) && !visited[nr][nc]) {
                visited[nr][nc] = 1;
                dist   [nr][nc] = dist[r][c] + 1;
                q_row[tail] = nr;
                q_col[tail] = nc;
                ++tail;
            }
        }
    }
    return -1;                               /* queue exhausted → unreachable */
}

/* ----------------------------------------------------------------------
 * Main – argument handling and output exactly as the original program.
 * ---------------------------------------------------------------------- */
int main(int argc, char *argv[])
{
    if (argc != 5) {
        puts("INVALID_CELL");
        return 0;
    }

    /* parse arguments (base 10) */
    long sr = strtol(argv[1], NULL, 10);
    long sc = strtol(argv[2], NULL, 10);
    long tr = strtol(argv[3], NULL, 10);
    long tc = strtol(argv[4], NULL, 10);

    /* range check – the original program required 0 ≤ coord < 5 */
    if (sr < 0 || sr >= N || sc < 0 || sc >= N ||
        tr < 0 || tr >= N || tc < 0 || tc >= N) {
        puts("INVALID_CELL");
        return 0;
    }

    /* wall check */
    if (!valid_cell((int)sr, (int)sc) || !valid_cell((int)tr, (int)tc)) {
        puts("INVALID_CELL");
        return 0;
    }

    /* start equals target → distance 0 */
    if (sr == tr && sc == tc) {
        printf("dist=%d\n", 0);
        return 0;
    }

    int d = bfs((int)sr, (int)sc, (int)tr, (int)tc);
    if (d < 0) {
        puts("UNREACHABLE");
    } else {
        printf("dist=%d\n", d);
    }
    return 0;
}
